// Compose manually (inside-out execution)
const EnhancedComponent = withAuth(withLoading(withLogger(Dashboard)));

// This creates:
// withAuth -> withLoading -> withLogger -> Dashboard

import { compose } from 'redux';

// compose reads left-to-right
const enhance = compose(
  withLogger,
  withLoading,
  withAuth
);

const EnhancedDashboard = enhance(Dashboard);
// Equivalent to: withAuth(withLoading(withLogger(Dashboard)))

// HOC approach
const Enhanced = withAuth(withLoading(MyComponent));

// Hooks approach
function MyComponent() {
  const { isAuthenticated } = useAuth();
  const { isLoading } = useLoading();
  // ...
}
